use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    match input {
        Value::String(hex_str) => {
            if hex_str.len() % 2 != 0 {
                return serde_json::Value::Null;
            }

            let mut bytes = Vec::with_capacity(hex_str.len() / 2);
            let mut chars = hex_str.chars().peekable();

            while let Some(c1) = chars.next() {
                let c2 = chars.next().unwrap_or(' ');

                let byte = match (c1.to_ascii_lowercase(), c2.to_ascii_lowercase()) {
                    ('0'..='9', '0'..='9') => {
                        let num1 = c1 as u8 - b'0';
                        let num2 = c2 as u8 - b'0';
                        num1 * 16 + num2
                    }
                    ('a'..='f', '0'..='9') => {
                        let num1 = c1 as u8 - b'a' + 10;
                        let num2 = c2 as u8 - b'0';
                        num1 * 16 + num2
                    }
                    ('0'..='9', 'a'..='f') => {
                        let num1 = c1 as u8 - b'0';
                        let num2 = c2 as u8 - b'a' + 10;
                        num1 * 16 + num2
                    }
                    ('a'..='f', 'a'..='f') => {
                        let num1 = c1 as u8 - b'a' + 10;
                        let num2 = c2 as u8 - b'a' + 10;
                        num1 * 16 + num2
                    }
                    _ => return serde_json::Value::Null,
                };

                bytes.push(byte);
            }

            serde_json::Value::Array(bytes.into_iter().map(serde_json::Value::from).collect())
        }
        _ => serde_json::Value::Null,
    }
}
